'use strict';
(()=>{
 const config=window.CREDIT_RUNTIME;const help=window.CREDIT_FIELD_HELP;const defaults={motion:'system',density:'comfortable',textSize:'standard'};const allowed={motion:['system','full','reduced'],density:['comfortable','compact'],textSize:['standard','large']};const key='credit-pme.interface.v1';
 let preferences={...defaults};try{const saved=JSON.parse(localStorage.getItem(key)||'{}');for(const k of Object.keys(defaults))if(allowed[k].includes(saved[k]))preferences[k]=saved[k]}catch{}
 const session={status:config.sessionEndpoint?'loading':'unconfigured',user:null,error:null};let helpOpener=null,uid=0,navFrame=0,lastRoute='',renderSequence=0,api=null,csrf=null;
 function motionReduced(){return preferences.motion==='reduced'||preferences.motion==='system'&&matchMedia('(prefers-reduced-motion: reduce)').matches}
 function applyPreferences(){document.documentElement.dataset.motion=motionReduced()?'reduced':'full';document.documentElement.dataset.density=preferences.density;document.documentElement.dataset.textSize=preferences.textSize}
 applyPreferences();matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',applyPreferences);
 function sameOrigin(path){const u=new URL(path,location.origin);if(u.origin!==location.origin||u.username||u.password)throw new Error('La connexion au service doit utiliser la même origine.');return u}
 async function endpoint(path,options={}){const u=sameOrigin(path);const method=options.method||'GET';const headers={Accept:'application/json'};if(options.body!==undefined)headers['Content-Type']='application/json';if(!['GET','HEAD'].includes(method)){if(!csrf)throw new Error('Actualisez votre session avant d’enregistrer.');headers['X-CSRF-Token']=csrf}const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),config.requestTimeoutMs);try{const response=await fetch(u,{...options,headers,body:options.body===undefined?undefined:JSON.stringify(options.body),credentials:'same-origin',redirect:'error',cache:'no-store',signal:controller.signal});if(response.status===401){session.status='signed_out';session.user=null;api=null;csrf=null;services.publishedReport=null;services.api=null;services.user=null;window.CreditJourney?.clear();throw new Error('Reconnectez-vous pour continuer.')}if(!response.ok)throw new Error(response.status===422?'Vérifiez les informations saisies : nom, adresse e-mail et téléphone.':response.status===403?'Actualisez votre session avant de poursuivre.':response.status===429?'Trop de tentatives. Réessayez plus tard.':'Le service de compte est momentanément indisponible.');if(response.status===204)return null;return await response.json()}catch(e){throw new Error(controller.signal.aborted?'Le service n’a pas répondu à temps.':e.message||'Connexion au service impossible.')}finally{clearTimeout(timer)}}
 async function refreshSession(){if(!config.sessionEndpoint)return;session.status='loading';updateServiceBadge();try{const data=await endpoint(config.sessionEndpoint);if(!data?.user?.id){session.status='signed_out';session.user=null}else{session.user=data.user;session.status='authenticated';if(config.csrfTokenEndpoint){const t=await endpoint(config.csrfTokenEndpoint);csrf=t?.token||null}if(config.apiBaseUrl){const base=sameOrigin(config.apiBaseUrl);api=new CreditApi({baseUrl:base.href,csrfProvider:()=>csrf,requireCsrf:true,timeoutMs:config.requestTimeoutMs,onUnauthorized:()=>{session.status='signed_out';session.user=null;api=null;csrf=null;services.publishedReport=null;services.api=null;services.user=null;window.CreditJourney?.clear();location.hash='profile';window.renderApp()}})}}if(api&&session.status==='authenticated'){window.configureCreditBackend(services,api,session.user);if(session.user.role!=='administrator')await services.loadAll()}session.error=null}catch(e){if(session.status!=='signed_out')session.status='error';session.error=e.message}updateServiceBadge();window.renderApp()}
 function updateServiceBadge(){window.CreditInstitutions?.links();const b=$('#service-status');b.textContent=session.status==='authenticated'?(services.user?.role==='administrator'?'Administration':'Mon espace'):session.status==='loading'?'Connexion…':session.status==='error'?'Service indisponible':'Espace de financement';b.dataset.state=session.status;const visitor=$('#visitor-notice');if(visitor)visitor.hidden=session.status!=='signed_out';if(session.status==='signed_out')b.textContent='Mode visiteur';const a=$('#switch-role');a.setAttribute('aria-label','Ouvrir le menu des sections')}
 const services={get ready(){return session.status==='authenticated'&&!!api&&!!csrf},publishedReport:null,
  async submitDraft(draft,payload){if(!this.ready)throw new Error('Le service d’envoi n’est pas connecté. Aucun dossier transmis.');return window.submitCreditDraft(api,draft,payload)}
 };window.CreditServices=services;
 function infoFor(control){const key=control.dataset.field||control.dataset.key||control.name||control.id;const label=control.getAttribute('aria-label')||control.labels?.[0]?.textContent?.trim()||control.closest('.field')?.querySelector('span')?.textContent||'Ce champ';const fallback=[label,control.type==='checkbox'?'Cochez cette case après avoir vérifié ce qui est indiqué.':control.type==='radio'?'Choisissez l’option qui correspond à votre demande.':'Renseignez '+label.toLocaleLowerCase('fr')+'.',''];const entry=help[key]||fallback;const hint=control.closest('.field')?.querySelector('small')?.textContent?.trim();return {key,title:entry[0],text:entry[1],example:entry[2],hint:hint&&hint!==entry[2]?hint:''}}
 function openHelp(button){const current=infoFor(button._control);const data={...current,hint:current.hint||button._help.hint};helpOpener=button;$('#field-help-title').textContent=data.title;const root=$('#field-help-text');root.replaceChildren();for(const text of [data.text,data.example,data.hint].filter(Boolean)){const p=document.createElement('p');p.textContent=text;root.append(p)}$('#field-help-dialog').showModal()}
 function closeHelp(){$('#field-help-dialog').close();helpOpener?.focus()}
 $('#close-field-help').onclick=closeHelp;$('#understood-help').onclick=closeHelp;$('#field-help-dialog').addEventListener('click',e=>{if(e.target===$('#field-help-dialog'))closeHelp()});
 function enhance(root){
  root.querySelectorAll('input,select,textarea').forEach(control=>{
   if(['hidden','file','submit','button'].includes(control.type)||control.dataset.infoReady)return;
   const data=infoFor(control);control.dataset.infoReady='true';if(!control.id)control.id='credit-field-'+(++uid);
   const button=document.createElement('button');button.type='button';button.className='field-info';button.textContent='i';button.setAttribute('aria-label','Aide : '+data.title);button.setAttribute('aria-haspopup','dialog');button.setAttribute('aria-controls','field-help-dialog');button._help=data;button._control=control;button.onclick=()=>openHelp(button);
   const field=control.closest('label.field');if(field){const div=document.createElement('div');div.className=field.className;while(field.firstChild)div.append(field.firstChild);field.replaceWith(div);const old=div.querySelector(':scope > span');const heading=document.createElement('div');heading.className='field-heading';const label=document.createElement('label');label.htmlFor=control.id;label.textContent=old?.textContent?.trim()||data.title;heading.append(label,button);old?old.replaceWith(heading):div.prepend(heading);div.querySelectorAll(':scope > small').forEach(e=>{if(e.id)e.hidden=true;else e.remove()});
   }else{const label=control.closest('label');if(label){const box=document.createElement('div');box.className=label.classList.contains('credit-option')?'option-info-wrap':'check-info-wrap';label.before(box);box.append(label,button)}else{const box=document.createElement('div');box.className='control-info-wrap';control.before(box);box.append(control,button)}}
   if(control.required)control.setAttribute('aria-required','true');
  });
  root.querySelectorAll('img').forEach(img=>{img.decoding='async';if(!img.hasAttribute('fetchpriority'))img.loading='lazy';img.addEventListener('error',()=>{img.classList.add('image-unavailable');img.setAttribute('alt',img.alt||'Image indisponible')},{once:true})});
 }
 function centerItem(container,item,animate){if(!container||!item)return;const c=container.getBoundingClientRect(),r=item.getBoundingClientRect();container.scrollTo({left:Math.max(0,container.scrollLeft+r.left-c.left-(container.clientWidth-r.width)/2),behavior:animate&&!motionReduced()?'smooth':'auto'})}
 function moveNavigation(animate=true){cancelAnimationFrame(navFrame);navFrame=requestAnimationFrame(()=>{const nav=$('.nav-scroll');const active=nav.querySelector('a.active');const marker=nav.querySelector('.nav-marker');marker.hidden=!active;nav.style.setProperty('--nav-edge',nav.clientWidth/2+'px');nav.querySelectorAll('a').forEach(a=>{if(a===active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});if(active){marker.style.width=active.offsetWidth+'px';nav.dataset.ready='true';marker.style.transform='translate3d('+active.offsetLeft+'px,0,0)';centerItem(nav,active,animate)}const route=location.hash.slice(1).split('/')[0]||'overview';const section=['choix','documents','verification'].includes(route)?'demande':route;document.querySelectorAll('[data-section]').forEach(a=>{const current=a.dataset.section===section;a.classList.toggle('active',current);if(current)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});const steps=$('.form-step-list');if(steps){steps.style.setProperty('--step-edge',steps.clientWidth/2+'px');centerItem(steps,steps.querySelector('[aria-current="step"]'),animate)}const rail=$('.journey-rail');if(rail){rail.style.setProperty('--rail-edge',rail.clientWidth/2+'px');centerItem(rail,rail.querySelector('.current'),animate)}})}
 const menuButton=$('#switch-role'),sectionMenu=$('#sections-dropdown');
 function closeSections(restore=false){sectionMenu.hidden=true;menuButton.setAttribute('aria-expanded','false');if(restore)menuButton.focus()}
 function openSections(focus=false){sectionMenu.hidden=false;menuButton.setAttribute('aria-expanded','true');if(focus)(sectionMenu.querySelector('[aria-current="page"]')||sectionMenu.querySelector('a')).focus()}
 menuButton.addEventListener('click',()=>sectionMenu.hidden?openSections():closeSections());
 menuButton.addEventListener('keydown',e=>{if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();openSections(true)}});
 sectionMenu.addEventListener('click',e=>{if(e.target.closest('a'))closeSections()});
 sectionMenu.addEventListener('keydown',e=>{if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();const links=[...sectionMenu.querySelectorAll('a')];const i=links.indexOf(document.activeElement);links[e.key==='Home'?0:e.key==='End'?links.length-1:(i+(e.key==='ArrowDown'?1:-1)+links.length)%links.length].focus()}});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!sectionMenu.hidden){e.preventDefault();closeSections(true)}});
 document.addEventListener('click',e=>{if(!e.target.closest('.section-menu'))closeSections()});
 document.addEventListener('focusin',e=>{if(!e.target.closest('.section-menu'))closeSections()});
 function activateNav(name){document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===name))}
 function heading(title,subtitle,nav){$('#page-title').textContent=title;$('#page-subtitle').textContent=subtitle;$('.eyebrow').textContent='VOTRE ESPACE';activateNav(nav)}
 function profile(){heading('Un espace à votre image.','Vos informations et vos accès.','profile');const user=session.user;const connected=session.status==='authenticated';const values={displayName:user?.display_name||'',email:user?.email||'',telephone:user?.telephone||''};$('#view').innerHTML=`<div class="account-layout"><section class="profile-card"><div class="profile-identity"><span class="profile-monogram" aria-hidden="true">${user?appendInitials(user.display_name||'Compte'):'↗'}</span><div><span class="mini-kicker">VOTRE PROFIL</span><h2>${user?safe(user.display_name||'Mon compte'):'Votre compte Crédix'}</h2><span class="account-state">${connected?'Connecté':session.status==='loading'?'Connexion en cours…':'Non connecté'}</span></div></div><form id="profile-form"><div class="field-grid">${[['displayName','Nom affiché','text'],['email','Adresse e-mail','email'],['telephone','Téléphone','tel']].map(([name,label,type])=>`<label class="field ${name==='displayName'?'wide':''}"><span>${label}</span><input name="${name}" type="${type}" autocomplete="${name==='displayName'?'name':name==='telephone'?'tel':'email'}" maxlength="${name==='displayName'?200:name==='telephone'?100:300}" value="${safe(values[name])}" ${connected?'':'readonly'}></label>`).join('')}</div><div class="profile-form-actions"><button class="primary" type="submit" ${connected&&config.profileEndpoint?'':'disabled'}>Enregistrer mes informations</button><span id="profile-message" role="status">${connected&&!config.profileEndpoint?'Modification du profil indisponible.':!connected?'Connectez votre compte pour gérer vos informations.':''}</span></div></form></section><aside class="account-photo photo-surface"><img src="assets/african-finance.jpg" alt="Un professionnel dans son espace de travail"><div><span class="glass-label">Votre espace personnel</span><h2>Vos projets.<br>Votre parcours.</h2></div></aside></div><div class="account-bottom"><section class="account-detail-card"><span class="mini-kicker">ACCÈS AU COMPTE</span><h3>${connected?'Votre session est active.':'Retrouvez votre espace.'}</h3><p>${session.error?safe(session.error):connected?'Vos droits d’accès sont gérés par votre institution.':'La connexion doit être disponible pour retrouver vos dossiers enregistrés.'}</p><div class="inline-buttons">${connected?`<button id="logout-action" class="outline" ${config.logoutUrl?'':'disabled'}>Se déconnecter</button>`:`<button id="login-action" class="outline" ${config.loginUrl?'':'disabled'}>Se connecter ↗</button>`}${config.sessionEndpoint?'<button class="text-button" id="retry-session">Actualiser la connexion ↻</button>':''}</div></section><section class="account-detail-card lavender"><span class="mini-kicker">CONFORT DE LECTURE</span><h3>Une interface à votre rythme.</h3><p>Ajustez les animations, la taille du texte et les espacements.</p><a href="#settings" class="text-button">Mes paramètres →</a></section></div>`;
  $('#profile-form').onsubmit=async e=>{e.preventDefault();if(!connected||!config.profileEndpoint||!e.target.reportValidity())return;const button=e.target.querySelector('button[type=submit]');button.disabled=true;button.textContent='Enregistrement…';const data=Object.fromEntries(new FormData(e.target));try{const result=await endpoint(config.profileEndpoint,{method:'PATCH',body:{display_name:data.displayName,email:data.email,telephone:data.telephone}});if(!result?.user?.id)throw new Error('Le service n’a pas confirmé la modification.');session.user=result.user;$('#profile-message').textContent='Informations enregistrées.';toast('Profil mis à jour.')}catch(error){$('#profile-message').textContent=error.message}finally{button.disabled=false;button.textContent='Enregistrer mes informations'}};
  if(user?.role==='administrator'){viewAccountCleanup();}if($('#retry-session'))$('#retry-session').onclick=refreshSession;if($('#login-action'))$('#login-action').onclick=()=>{openLogin()};if($('#logout-action'))$('#logout-action').onclick=async()=>{try{await endpoint(config.logoutUrl,{method:'POST'});session.user=null;session.status='signed_out';api=null;csrf=null;services.publishedReport=null;services.api=null;services.user=null;window.CreditJourney?.clear();location.hash='profile';window.renderApp()}catch(e){toast(e.message)}};
 }
 function viewAccountCleanup(){const security=document.querySelector('#view .account-bottom .account-detail-card');if(security)$('#view').append(security);document.querySelectorAll('#view .account-photo,#view .account-bottom').forEach(n=>n.remove());const eyebrow=document.querySelector('#view .mini-kicker');if(eyebrow)eyebrow.textContent='COMPTE ADMINISTRATEUR';$('#page-title').textContent='Mon compte administrateur.';$('#page-subtitle').textContent='Coordonnées du compte et fermeture de session.';}
 function openLogin(){openModal('<h2>Se connecter</h2><form id="web-login"><div class="field-grid"><label class="field"><span>Identifiant</span><input name="username" autocomplete="username" required maxlength="100"></label><label class="field"><span>Mot de passe</span><input name="password" type="password" autocomplete="current-password" required maxlength="1024"></label></div><p id="login-message" role="status"></p><button class="primary" type="submit">Ouvrir ma session</button><a class="text-link" href="/login.html#register">Créer un compte par e-mail ou téléphone →</a></form>','ACCÈS CRÉDIX');enhance($('#modal'));$('#web-login').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button[type=submit]');b.disabled=true;try{const body=Object.fromEntries(new FormData(e.target));const r=await fetch(sameOrigin(config.loginUrl),{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',redirect:'error',body:JSON.stringify(body)});if(!r.ok)throw new Error(r.status===429?'Trop de tentatives. Réessayez plus tard.':'Identifiants invalides ou accès indisponible.');$('#modal').close();await refreshSession()}catch(err){$('#login-message').textContent=err.message}finally{b.disabled=false}}}
 function appendInitials(name){return safe(name.split(/\s+/).filter(Boolean).slice(0,2).map(s=>s[0]).join('').toUpperCase())}
 function settings(){heading('Votre rythme. Vos préférences.','Un espace qui s’adapte à votre usage.','settings');$('#view').innerHTML=`<div class="settings-layout"><form id="settings-form"><section class="form-panel settings-panel"><span class="mini-kicker">AFFICHAGE & NAVIGATION</span><h2>Le confort, dans les détails.</h2><div class="settings-fields">${[['motion','Animations',[['system','Suivre mon appareil'],['full','Fluides et complètes'],['reduced','Réduire les mouvements']]],['density','Espacement',[['comfortable','Aéré'],['compact','Compact']]],['textSize','Taille du texte',[['standard','Standard'],['large','Agrandie']]]].map(([name,label,options])=>`<label class="field"><span>${label}</span><select name="${name}">${options.map(([v,l])=>`<option value="${v}" ${preferences[name]===v?'selected':''}>${l}</option>`).join('')}</select></label>`).join('')}</div><div class="settings-actions"><button class="primary" type="submit">Enregistrer mes préférences</button><button class="text-button" type="button" id="reset-preferences">Rétablir les valeurs par défaut</button></div><p id="settings-status" role="status">Préférences conservées sur cet appareil.</p></section></form><aside><section class="account-detail-card lavender"><span class="mini-kicker">RÉGION</span><h3>Un cadre clair.</h3><div class="setting-readonly"><span>Langue</span><strong>Français</strong></div><div class="setting-readonly"><span>Devise</span><strong>Franc CFA · XOF</strong></div></section><section class="account-detail-card"><span class="mini-kicker">VIE PRIVÉE</span><h3>Votre choix reste le vôtre.</h3><p>Les réglages d’affichage sont séparés des données de vos demandes.</p><button class="text-button" id="settings-privacy">Données et confidentialité →</button></section></aside></div>`;
  $('#settings-form').onsubmit=e=>{e.preventDefault();const form=new FormData(e.target);for(const name of Object.keys(defaults)){const v=form.get(name);if(!allowed[name].includes(v))return;preferences[name]=v}applyPreferences();try{localStorage.setItem(key,JSON.stringify(preferences));$('#settings-status').textContent='Préférences enregistrées sur cet appareil.';toast('Vos préférences sont enregistrées.')}catch{$('#settings-status').textContent='Réglages appliqués. Leur conservation est bloquée par le navigateur.'}moveNavigation()};$('#reset-preferences').onclick=()=>{preferences={...defaults};applyPreferences();try{localStorage.removeItem(key)}catch{}window.renderApp();toast('Préférences réinitialisées.')};$('#settings-privacy').onclick=()=>$('#privacy').click();
 }
 function compactCopy(){const exact=new Map([['Seules les informations utiles à votre dossier.',''],['Vos réponses sont déclaratives. Un champ inconnu reste inconnu ; zéro signifie réellement zéro.',''],['Les périodes, les montants et les preuves se lisent ensemble.',''],['La suite : vos justificatifs.','Vos justificatifs, ensuite.'],['Vous pourrez importer les PDF, ajouter des photos de scans, contrôler l’ordre des pages, puis vérifier la cohérence du dossier.',''],['L’OCR français et les contrôles techniques du serveur interviendront après connexion du backend.',''],['Ces catégories décrivent votre projet. Elles ne constituent pas des offres de prêt.',''],['Préparez votre prochain financement.','']]);$('#view').querySelectorAll('p,small').forEach(el=>{const text=el.textContent.trim();if(exact.has(text)){const value=exact.get(text);value?el.textContent=value:el.remove()}})}
 const original=window.renderApp;
 window.renderApp=()=>{const sequence=++renderSequence;const current=location.hash.slice(1)||'overview';const view=$('#view');try{if(current==='profile')profile();else if(current==='settings')settings();else if(!window.CreditInstitutions?.route(view,current)&&!window.CreditBanking?.route(view,current))original();compactCopy();if(services.user?.role!=='administrator'){if(!current.startsWith('bank-')&&!current.startsWith('institution-review'))services.enhanceView?.(view);window.CreditFinancialV2?.mount(view);window.CreditBanking?.mount(view,current);}enhance(view);if(services.user?.role!=='administrator'){window.CreditHomeVideos?.mount(view);window.CreditBudget?.mount(view);}document.body.classList.toggle('is-filling',!!view.querySelector('#journey-form'));if(window.CreditJourney?.getDraft()?.reviewState==='awaiting_review'){view.querySelectorAll('#journey-form input,#journey-form textarea,#journey-form select,#document-meta input,#document-meta select,[data-remove-doc],[data-add-pages],[data-remove-page],[data-rotate],[data-move],[data-crop],[data-remove-period],[data-remove-debt],[data-remove-history],#add-period,#add-debt,#add-history,#save-draft,#import-files,#scan-image').forEach(c=>c.disabled=true);const submitted=view.querySelector('#verification-form button[type=submit]');if(submitted){submitted.disabled=true;submitted.textContent='Dossier transmis ✓';const message=$('#submission-message');if(message)message.textContent='Vérification des documents en attente.'}}view.setAttribute('aria-busy','false');$('#new-request').hidden=['profile','settings'].includes(current)||['administrator','bank_agent','bank_manager'].includes(services.user?.role);updateServiceBadge();if(current!==lastRoute){closeSections();if($('#modal').open)$('#modal').close();if($('#field-help-dialog').open)$('#field-help-dialog').close();view.classList.remove('page-arrive');requestAnimationFrame(()=>{if(sequence===renderSequence)view.classList.add('page-arrive')});if(lastRoute&&document.activeElement?.tagName!=='INPUT'&&document.activeElement?.tagName!=='TEXTAREA'){const focusTarget=document.body.classList.contains('is-filling')?view.querySelector('.form-panel h2'):$('#page-title');if(focusTarget){focusTarget.tabIndex=-1;focusTarget.focus({preventScroll:true})}}if(document.body.classList.contains('is-filling'))window.scrollTo({top:0,behavior:'auto'});lastRoute=current}moveNavigation();}catch{view.innerHTML='<section class="release-error"><h2>Cette page n’a pas pu s’ouvrir.</h2><p>Vous pouvez réessayer sans recharger votre demande.</p><button class="outline" id="retry-view">Réessayer ↻</button><a class="text-button" href="#overview">Revenir à l’accueil →</a></section>';$('#retry-view').onclick=()=>window.renderApp();view.setAttribute('aria-busy','false')}};
 $('.skip-link').onclick=e=>{e.preventDefault();$('#main-content').focus({preventScroll:true});$('#main-content').scrollIntoView({block:'start',behavior:'auto'})};
 $('#history-back').onclick=()=>history.back();$('#history-forward').onclick=()=>history.forward();let resizeFrame;addEventListener('resize',()=>{cancelAnimationFrame(resizeFrame);resizeFrame=requestAnimationFrame(()=>moveNavigation(false))});addEventListener('online',()=>{document.documentElement.dataset.online='true'});addEventListener('offline',()=>{document.documentElement.dataset.online='false';toast('Vous êtes hors connexion. Vos réponses restent sur cette page.')});
 addEventListener('beforeunload',event=>{const d=window.CreditJourney?.getDraft();if(d&&d.reviewState!=='awaiting_review'&&(d.form.name||d.documents.length)){event.preventDefault();event.returnValue=''}});
 document.fonts?.ready.then(()=>moveNavigation(false));
window.CreditExperience={enhance,moveNavigation,refreshSession,get preferences(){return {...preferences}},get session(){return {status:session.status}}};window.renderApp();refreshSession();
})();
